\relax{def:axisymmetric}
For $f,\psi\in L^2(S^2)$ with axisymmetric kernel $\psi$, \mbox{\it i.e.}\ $\psi_{\ell m}=\psi_{\ell0}\delta_{m0}$, the axisymmetric convolution is
\relax{equation}
  (f \odot \psi)(\omega) = \langle f, \mathcal{R}_\omega \psi \rangle = \int_{S^2} f(\omega')\, (\mathcal{R}_\omega \psi)^{*}(\omega') \,\mathrm{d}\mu(\omega'),
  \qquad \mathcal{R}_\omega = \mathcal{R}_{(\varphi,\theta,0)} .
  \relax{eq:axisymmetric-conv}
\relax{equation}

\relax{def:driscoll-healy}
For $f, h \in L^2(S^2)$, the left convolution is
\relax{equation}
  (f \star_{\mathrm{L}} h)(\omega) = \int_{\mathrm{SO}(3)} f(\rho\eta)\, h(R_\rho^{-1}\omega) \,\mathrm{d}\mu(\rho) .
  \relax{eq:driscoll-healy}
\relax{equation}

\relax{def:directional}
For $f, \psi \in L^2(S^2)$, the directional convolution is
\relax{equation}
  (f \circledast \psi)(\rho) = \langle f, \mathcal{R}_\rho \psi \rangle = \int_{S^2} f(\omega)\, (\mathcal{R}_\rho \psi)^{*}(\omega) \,\mathrm{d}\mu(\omega), \qquad \rho \in \mathrm{SO}(3) .
  \relax{eq:directional-conv}
\relax{equation}

\relax{def:group-conv}
For $\Psi, F \in L^2(\mathrm{SO}(3))$, the group convolution is
\relax{equation}
  (\Psi \star F)(\rho) = \langle F, \pi_{G}(\rho)\Psi \rangle = \int_{\mathrm{SO}(3)} \Psi^{*}(\rho^{-1}\rho')\, F(\rho') \,\mathrm{d}\mu(\rho'),
  \qquad (\pi_{G}(\rho)\Psi)(\rho') = \Psi(\rho^{-1}\rho') ,
  \relax{eq:group-conv}
\relax{equation}
where $\pi_{G}$ is the left regular representation of $\mathrm{SO}(3)$.

\relax{def:spin-directional}
For $\prescript{}{s}{f}, \prescript{}{s}{\psi} \in L^2_{s}(S^2)$, the directional spin convolution is
\relax{equation}
  (\prescript{}{s}{f} \circledast \prescript{}{s}{\psi})(\rho) = \langle \prescript{}{s}{f}, \mathcal{R}_\rho\, \prescript{}{s}{\psi} \rangle
  = \int_{S^2} \prescript{}{s}{f}(\omega)\, (\mathcal{R}_\rho\, \prescript{}{s}{\psi})^{*}(\omega) \,\mathrm{d}\mu(\omega),
  \qquad \rho \in \mathrm{SO}(3) .
  \relax{eq:spin-directional}
\relax{equation}

\relax{def:spin-axisymmetric}
For $\prescript{}{s}{f} \in L^2_{s}(S^2)$ and an axisymmetric kernel $\prescript{}{s}{\Phi}$, \mbox{\it i.e.}\ $\mathcal{R}_{(0,0,\gamma)}\,\prescript{}{s}{\Phi} = \prescript{}{s}{\Phi}$ or equivalently $\prescript{}{s}{\Phi}_{\ell m} = \prescript{}{s}{\Phi}_{\ell 0}\delta_{m0}$, the axisymmetric spin convolution is
\relax{equation}
  (\prescript{}{s}{f} \odot \prescript{}{s}{\Phi})(\omega) = \langle \prescript{}{s}{f}, \mathcal{R}_\omega\, \prescript{}{s}{\Phi} \rangle, \qquad \mathcal{R}_\omega = \mathcal{R}_{(\varphi,\theta,0)} .
  \relax{eq:spin-axisymmetric}
\relax{equation}

\relax{def:standard-correlation}
For $f, \psi \in L^2(S^2)$ with $\psi$ not necessarily axisymmetric, the standard correlation is the directional convolution restricted to the rotations with vanishing third Euler angle,
\relax{equation}
  (f \circledast \psi)(R_\omega) = \langle f, \mathcal{R}_\omega \psi \rangle, \qquad R_\omega = R(\varphi,\theta,0) .
  \relax{eq:standard-correlation}
\relax{equation}

\relax{def:commutative-anisotropic}
For $f, h \in L^2(S^2)$, the commutative anisotropic convolution of Sadeghi \mbox{\it et al.}\ \relax{sadeghi2012commutative,khalid2012anisotropic} is
\relax{equation}
  (h \odot_{\mathrm{S}} f)(\theta,\varphi) = \int_{S^2} \big(\mathcal{R}_{(\varphi,\theta,\pi-\varphi)} h\big)(\omega')\, f(\omega') \,\mathrm{d}\mu(\omega') .
  \relax{eq:commutative-anisotropic}
\relax{equation}

\relax{def:sifting}
For $f, g \in L^2(S^2)$, harmonic multiplication \relax{kennedy2011azimuthally} and the sifting convolution \relax{roddy2021sifting} are defined in harmonic space by
\relax{equation}
  (g \odot_{\mathrm{K}} f)_{\ell m} = g_{\ell m}\, f_{\ell m},
  \qquad
  (f \circledcirc g)_{\ell m} = f_{\ell m}\, g^{*}_{\ell m} ,
  \relax{eq:sifting}
\relax{equation}
the latter arising in real space as $(f \circledcirc g)(\omega) = \langle \mathcal{T}_\omega f, g\rangle$ for the translation operator $(\mathcal{T}_{\omega'} f)(\omega) = \sum_{\ell m} f_{\ell m}\, Y_{\ell m}(\omega')\, Y_{\ell m}(\omega)$.

\relax{def:synthesis}
For $W \in L^2(\mathrm{SO}(3))$ and $\psi \in L^2(S^2)$, the synthesis is
\relax{equation}
  (W \circledast^{\dagger} \psi)(\omega) = \int_{\mathrm{SO}(3)} W(\rho)\, (\mathcal{R}_\rho \psi)(\omega) \,\mathrm{d}\mu(\rho),
  \qquad
  (W \circledast^{\dagger} \psi)_{\ell m} = \sum_{n=-\ell}^{\ell} W^{\ell}_{mn}\, \psi_{\ell n} ,
  \relax{eq:synthesis}
\relax{equation}
where the harmonic form follows by expanding $W$ and $\psi$ and noting \eqref{eq:rotation-coeffs}.

\relax{def:twist}
The twist $\hbar : G/H \times G \to H$ is defined by
\relax{equation}
  g\, s(x) = s(gx)\, \hbar(x,g), \qquad \hbar(x,g) = s(gx)^{-1}\, g\, s(x) .
  \relax{eq:twist}
\relax{equation}
We write $\hbar(g) = \hbar(x_0, g) = s(gx_0)^{-1} g$ for the twist at the base point.

\relax{def:mackey}
A Mackey function of type $\rho$ is a map $F : G \to V$ with $F(gh) = \rho(h^{-1})F(g)$ for all $g \in G$, $h \in H$.  For $\rho = \rho^{(s)}$ the condition reads $F(g R_z(\gamma)) = e^{-\mathrm{i} s\gamma}F(g)$, and we write
\relax{equation}
  \mathcal{M}_{s} = \{ F \in L^2(\mathrm{SO}(3)) : F(\,\cdot\,R_z(\gamma)) = e^{-\mathrm{i} s\gamma}F  
