\relax{def:lift}
For $s \in \mathbb{Z}$ define the lift $\Lambda_{s} : L^2_{s}(S^2) \to L^2(\mathrm{SO}(3))$ and its adjoint, the projection $\Lambda_{s}^{\dagger} : L^2(\mathrm{SO}(3)) \to L^2_{s}(S^2)$, by
\relax{equation}
  (\Lambda_{s} f)(\alpha,\beta,\gamma) = \frac{1}{\sqrt{2\pi}}\, e^{-\mathrm{i} s\gamma}\, f(\beta,\alpha),
  \qquad
  (\Lambda_{s}^{\dagger} F)(\beta,\alpha) = \frac{1}{\sqrt{2\pi}} \int_0^{2\pi} e^{\mathrm{i} s\gamma}\, F(\alpha,\beta,\gamma) \,\mathrm{d}\gamma .
  \relax{eq:lift-proj}
\relax{equation}

\relax{lem:lift}
Let $s \in \mathbb{Z}$.
\relax{enumerate}
  \item[(a)] $\Lambda_{s}$ is an isometry of $L^2_{s}(S^2)$ onto $\mathcal{M}_{s}$; $\Lambda_{s}^{\dagger}\Lambda_{s} = \operatorname{Id}$ and $\Lambda_{s}\Lambda_{s}^{\dagger}$ is the orthogonal projector onto $\mathcal{M}_{s}$.  The subspaces $\mathcal{M}_{s}$ are mutually orthogonal and $L^2(\mathrm{SO}(3)) = \widehat{\bigoplus}_{s \in \mathbb{Z}} \mathcal{M}_{s}$.
  \item[(b)] On $\mathcal{M}_{s}$ the projection is evaluation on the section: $\Lambda_{s}^{\dagger} F = \sqrt{2\pi}\, F \circ s$.
  \item[(c)] In harmonic space,
  \relax{equation}
    (\Lambda_{s} f)^{\ell}_{mn} = (-1)^s \sqrt{\frac{8\pi^2}{2\ell+1}}\; \prescript{}{s}{f}_{\ell m}\, \delta_{n,-s},
    \qquad
    (\Lambda_{s}^{\dagger} F)_{\ell m} = (-1)^s \sqrt{\frac{2\ell+1}{8\pi^2}}\; F^{\ell}_{m,-s} ,
    \relax{eq:lift-harmonic}
  \relax{equation}
  where the coefficients on the sphere are taken with respect to the spin-$s$ harmonics.
  \item[(d)] $\Lambda_{s}\, \prescript{}{s}{Y}_{\ell m} = (-1)^s \sqrt{\frac{2\ell+1}{8\pi^2}}\; D^{\ell *}_{m,-s}$: lifted spin harmonics are unit-norm Wigner functions.
  \item[(e)] $\pi_{G}(g)\Lambda_{s} = \Lambda_{s}\pi_{s}(g)$ and $\Lambda_{s}^{\dagger}\pi_{G}(g) = \pi_{s}(g)\Lambda_{s}^{\dagger}$ for all $g \in \mathrm{SO}(3)$, where $\pi_{G}$ is the left regular representation of $\mathrm{SO}(3)$ on $L^2(\mathrm{SO}(3))$, $(\pi_{G}(g)F)(g') = F(g^{-1}g')$, and $\pi_{s}$ is the representation of $\mathrm{SO}(3)$ on spin-$s$ fields induced from $\rho^{(s)}$; both are developed in Sec.~\relax{sec:lifting:induced}, where (e) is proved as Proposition~\relax{prop:intertwining}.
\relax{enumerate}

\relax{prop:intertwining}
$\pi_{s}$ is unitary, $\pi_{G}(g)\Lambda_{s} = \Lambda_{s}\pi_{s}(g)$, and
\relax{equation}
  (\pi_{s}(g) f)(x) = \rho^{(s)}\big(\hbar(x, g^{-1})^{-1}\big)\, f(g^{-1}x) .
  \relax{eq:induced-explicit}
\relax{equation}
On the sphere, $\pi_{s}(R_\rho)$ is the rotation $\mathcal{R}_\rho$ of a spin field defined in \eqref{eq:spin-rotation}: $\hbar(x, R_\rho^{-1}) = R_z(\vartheta)$ with $\vartheta$ the third Euler angle of $R_\rho^{-1}R_x$ away from the coordinate singularities, hence almost everywhere.

Writing $(\Lambda_{s}f)(g') = \rho^{(s)}(\hbar(g')^{-1})f(g'H)/\sqrt{2\pi}$, we have
\relax{equation}
  (\pi_{G}(g)\Lambda_{s}f)(g') = \frac{1}{\sqrt{2\pi}}\,\rho^{(s)}\big(\hbar(g^{-1}g')^{-1}\big)\,f(g^{-1}g'H),
\relax{equation}
and Lemma~\relax{lem:twist-composition} with $x = x_0$, $g_1 = g^{-1}$ and $g_2 = g'$ splits $\hbar(g^{-1}g')$ into $\hbar(g'H,g^{-1})\,\hbar(g')$, from which \eqref{eq:induced-explicit} and the intertwining relation follow.  Unitarity follows since $\pi_{G}$ is unitary and $\Lambda_{s}$ is an isometry onto an invariant subspace.  On the sphere, $R_\rho^{-1}R_x = s(R_\rho^{-1}x)R_z(\vartheta)$ by the definition of $\vartheta$, hence $\hbar(x,R_\rho^{-1}) = R_z(\vartheta)$ and \eqref{eq:induced-explicit} reduces to \eqref{eq:spin-rotation}.  The details are given in Appendix~\relax{app:proofs}.

\relax{def:lifted-conv}
For a kernel $\Psi \in L^2(\mathrm{SO}(3))$ and spins $s, s' \in \mathbb{Z}$ define the four operators
\relax{alignat}{2}
  \mathcal{C}_{s\to s'}[\Psi] &= \Lambda_{s'}^{\dagger}\,(\Psi \star \Lambda_{s}\,\cdot\,) &&: L^2_{s}(S^2) \to L^2_{s'}(S^2), \notag\\
  \mathcal{C}_{s\to G}[\Psi]  &= \Psi \star \Lambda_{s}\,\cdot               &&: L^2_{s}(S^2) \to L^2(\mathrm{SO}(3)), \notag\\
  \mathcal{C}_{G\to s'}[\Psi] &= \Lambda_{s'}^{\dagger}\,(\Psi \star \cdot\,)          &&: L^2(\mathrm{SO}(3)) \to L^2_{s'}(S^2), \notag\\
  \mathcal{C}_{G\to G}[\Psi]  &= \Psi \star \cdot                          &&: L^2(\mathrm{SO}(3)) \to L^2(\mathrm{SO}(3)) ,
  \relax{eq:lifted-conv}
\relax{alignat}
with $\star$ the group convolution of Definition~\relax{def:group-conv}.

\relax{thm:harmonic}
Let $\Psi \in L^2(\mathrm{SO}(3))$, $s, s' \in \mathbb{Z}$, and let $\widetilde{\Psi}(g) = \Psi^{*}(g^{-1})$.  For $\lvert m\rvert, \lvert n\rvert \le \ell$, with $\ell \ge \lvert s\rvert$ whenever the input is a spin-$s$ field and $\ell \ge \lvert s'\rvert$ whenever the output is a spin-$s'$ field,
\relax{align}
  \big(\mathcal{C}_{s\to G}[\Psi]\, \prescript{}{s}{f}\big)^{\ell}_{mn} &= (-1)^s \sqrt{\frac{8\pi^2}{2\ell+1}}\; \prescript{}{s}{f}_{\ell m}\; \Psi^{\ell *}_{n,-s} ,
  \relax{eq:harmonic-sG}\\
  \big(\mathcal{C}_{s\to s'}[\Psi]\, \prescript{}{s}{f}\big)_{\ell m} &= (-1)^{s+s'}\; \prescript{}{s}{f}_{\ell m}\; \Psi^{\ell *}_{-s',-s} ,
  \relax{eq:harmonic-ss}\\
  \big(\mathcal{C}_{G\to s'}[\Psi]\, F\big)_{\ell m} &= (-1)^{s'} \sqrt{\frac{2\ell+1}{8\pi^2}}\; \sum_{m'=-\ell}^{\ell} F^{\ell}_{mm'}\; \Psi^{\ell *}_{-s',m'} ,
  \relax{eq:harmonic-Gs}\\
  \big(\mathcal{C}_{G\to G}[\Psi]\, F\big)^{\ell}_{mn} &= \sum_{m'=-\ell}^{\ell} F^{\ell}_{mm'}\; \Psi^{\ell *}_{nm'} ,
  \relax{eq:harmonic-GG}
\relax{align}
and the output of $\mathcal{C}_{s\to s'}[\Psi]$ has no component of degree $\ell < \max(\lvert s\rvert,\lvert s'\rvert)$.  All four operators are bounded and $\mathrm{SO}(3)$-equivariant for every $\Psi$: $\mathcal{C}_{s\to s'}[\Psi]\,\pi_{s}(g) = \pi_{s'}(g)\,\mathcal{C}_{s\to s'}[\Psi]$ and correspondingly with $\pi_{G}$ in place of $\pi_{s}$ or $\pi_{s'}$.  Their adjoints are $\big(\mathcal{C}_{s\to G}[\Psi]\big)^{\dagger} = \mathcal{C}_{G\to s}[\widetilde\Psi]$, $\big(\mathcal{C}_{s\to s'}[\Psi]\big)^{\dagger} = \mathcal{C}_{s'\to s}[\widetilde\Psi]$ and $\big(\mathcal{C}_{G\to G}[\Psi]\big)^{\dagger} = \mathcal{C}_{G\to G}[\widetilde\Psi]$.

\relax{prop:composition}
The four families of Definition~\relax{def:lifted-conv} are closed under composition, and composing multiplies kernel blocks: for kernels $\Psi_1, \Psi_2 \in L^2(\mathrm{SO}(3))$,
\relax{equation}
  \mathcal{C}_{G\to G}[\Psi_2]\,\mathcal{C}_{G\to G}[\Psi_1] = \mathcal{C}_{G\to G}[\Psi_3], \qquad \Psi_3^{\ell} = \Psi_2^{\ell}\,\Psi_1^{\ell},
  \relax{eq:composition-GG}
\relax{equation}
and likewise $\mathcal{C}_{G\to s''}[\Psi_2]\,\mathcal{C}_{s\to G}[\Psi_1] = \mathcal{C}_{s\to s''}[\Psi_3]$, $\mathcal{C}_{G\to G}[\Psi_2]\,\mathcal{C}_{s\to G}[\Psi_1] = \mathcal{C}_{s\to G}[\Psi_3]$ and $\mathcal{C}_{G\to s''}[\Psi_2]\,\mathcal{C}_{G\to G}[\Psi_1] = \mathcal{C}_{G\to s''}[\Psi_3]$ with the same $\Psi_3$.  When the intermediate stage is a spin-$s'$ field only the intermediate index $-s'$ is retained: $\mathcal{C}_{s'\to s''}[\Psi_2]\,\mathcal{C}_{s\to s'}[\Psi_1] = \mathcal{C}_{s\to s''}[\Psi_3]$ with $(\Psi_3)^{\ell}_{-s'',-s} = (\Psi_2)^{\ell}_{-s'',-s'}\,(\Psi_1)^{\ell}_{-s',-s}$, so that the multipliers of \eqref{eq:harmonic-ss} multiply, $c^{(3)}_\ell = c^{(2)}_\ell c^{(1)}_\ell$; correspondingly $\mathcal{C}_{s'\to G}[\Psi_2]\,\mathcal{C}_{s\to s'}[\Psi_1] = \mathcal{C}_{s\to G}[\Psi_3]$ with $(\Psi_3)^{\ell}_{n,-s} = (\Psi_2)^{\ell}_{n,-s'}(\Psi_1)^{\ell}_{-s',-s}$.

\relax{cor:constraint}
The following are equivalent:
\relax{enumerate}
  \item[(i)] $\Psi \star \Lambda_{s} f \in \mathcal{M}_{s'}$ for all $f \in L^2_{s}(S^2)$;
  \item[(ii)] $\Psi^{\ell}_{n,-s} = 0$ for all $n \ne -s'$ and all $\ell \ge \lvert s\rvert$;
  \item[(iii)] the type-$s$ right-isotypic part $\Psi^{(s)}(g) = \frac{1}{2\pi}\int_0^{2\pi}\Psi(gR_z(\gamma))\,e^{\mathrm{i} s\gamma}\,\mathrm{d}\gamma$ of the kernel satisfies the two-sided constraint
  \relax{equation}
    \Psi^{(s)}\big(R_z(\chi_1)\, g\, R_z(\chi_2)\big) = e^{-\mathrm{i} s'\chi_1}\; \Psi^{(s)}(g)\; e^{-\mathrm{i} s\chi_2}
    \qquad 
