   {\hbox{{\everymath{\displaystyle     }for all }}} 
   {\hbox{{\everymath{\textstyle        }for all }}} 
   {\hbox{{\everymath{\scriptstyle      }\%\ssf@size\sf@size\selectfontfor all }}} 
   {\hbox{{\everymath{\scriptscriptstyle}\%\ssf@size\ssf@size\selectfontfor all }}} 
  \glb@settings
