 \fi
 \chi_1, \chi_2 .
    \relax{eq:two-sided}
  \relax{equation}
\relax{enumerate}
In that case $\mathcal{C}_{s\to s'}[\Psi] f = \sqrt{2\pi}\,(\Psi \star \Lambda_{s} f)\circ s$, the constrained part of the kernel is
\relax{equation}
  \Psi^{(s)}(\alpha,\beta,\gamma) = \sum_{\ell \ge \max(\lvert s\rvert,\lvert s'\rvert)} \frac{2\ell+1}{8\pi^2}\; \Psi^{\ell}_{-s',-s}\; e^{-\mathrm{i} s'\alpha}\, d^{\ell}_{-s',-s}(\beta)\, e^{-\mathrm{i} s\gamma} ,
  \relax{eq:constrained-kernel}
\relax{equation}
where the series converges in $L^2$.  For every kernel lifted from a spin-$s$ field, $\Psi=\Lambda_{s}\psi$, whether or not projection is lossless,
\relax{equation}
  \big(\mathcal{C}_{s\to s'}[\Lambda_{s}\psi]\, \prescript{}{s}{f}\big)_{\ell m} = (-1)^{s'} \sqrt{\frac{8\pi^2}{2\ell+1}}\; \prescript{}{s}{f}_{\ell m}\; \prescript{}{s}{\psi}^{*}_{\ell,-s'} .
  \relax{eq:harmonic-ss-lifted}
\relax{equation}
For such a lifted kernel, losslessness is equivalent to $\prescript{}{s}{\psi}_{\ell m}=\prescript{}{s}{\psi}_{\ell,-s'}\delta_{m,-s'}$.

\relax{thm:classification}
Let $T : L^2_{s}(S^2) \to L^2_{s'}(S^2)$ be a bounded linear map with $T\pi_{s}(g) = \pi_{s'}(g)T$ for all $g \in \mathrm{SO}(3)$.  Then there is a unique bounded sequence $(c_\ell)_{\ell \ge \max(\lvert s\rvert,\lvert s'\rvert)}$ such that
\relax{equation}
  (T\, \prescript{}{s}{f})_{\ell m} = c_\ell\; \prescript{}{s}{f}_{\ell m}
  \qquad  
