   {\hbox{{\everymath{\displaystyle     }for all }}} 
   {\hbox{{\everymath{\textstyle        }for all }}} 
   {\hbox{{\everymath{\scriptstyle      }\%\ssf@size\sf@size\selectfontfor all }}} 
   {\hbox{{\everymath{\scriptscriptstyle}\%\ssf@size\ssf@size\selectfontfor all }}} 
  \glb@settings
 \else
  \mbox{for all } 
 \fi
 \ell \ge \max(\lvert s\rvert,\lvert s'\rvert),\ \lvert m \rvert \le \ell ,
  \relax{eq:classification}
\relax{equation}
and $T$ annihilates the input components with degrees absent from the target; conversely every bounded sequence defines such a $T$, with $\lVert T\rVert = \sup_\ell\lvert c_\ell\rvert$.  Moreover:
\relax{enumerate}
  \item[(a)] $T = \mathcal{C}_{s\to s'}[\Psi]$ for some $\Psi \in L^2(\mathrm{SO}(3))$ if and only if $\sum_\ell (2\ell+1)\lvert c_\ell\rvert^2 < \infty$, \mbox{\it i.e.}\ if and only if $T$ is Hilbert--Schmidt.  The kernel is not unique, but the representative whose entire kernel satisfies the two-sided law \eqref{eq:two-sided}, with $\Psi$ in place of $\Psi^{(s)}$, is unique: $\Psi_T{}^{\ell}_{-s',-s} = (-1)^{s+s'}c^{*}_{\ell}$ and all other Wigner coefficients are zero.
  \item[(b)] Every bounded $T$ is $\mathcal{C}_{s\to s'}[\Psi_T]$ in the sense of Fourier multipliers, with $\Psi_T$ the distribution on $\mathrm{SO}(3)$ with the Wigner coefficients of (a).
  \item[(c)] Set $d_\ell = 2\ell+1$ and $a_\ell = d_\ell/(8\pi^2)$.  The equivariant maps of the other three types act on coefficients as
  \relax{equation}
    (T_{s\to G}f)^\ell_{mn} = u^\ell_n\,\prescript{}{s}{f}_{\ell m},\qquad
    (T_{G\to s'}F)_{\ell m} = \sum_k v^\ell_k F^\ell_{mk},\qquad
    (T_{G\to G}F)^\ell = F^\ell B^\ell .
    \relax{eq:classification-blocks}
  \relax{equation}
  They are bounded if and only if the respective bounds
  \relax{align}
    \lVert T_{s\to G}\rVert &= \sup_{\ell\ge\lvert s\rvert}\sqrt{a_\ell}\,\lVert u^\ell\rVert_2 < \infty, \notag\\
    \lVert T_{G\to s'}\rVert &= \sup_{\ell\ge\lvert s'\rvert}\frac{\lVert v^\ell\rVert_2}{\sqrt{a_\ell}} < \infty,\qquad
    \lVert T_{G\to G}\rVert = \sup_{\ell\ge0}\lVert B^\ell\rVert_{\mathrm{op}} < \infty
    \relax{eq:classification-norms}
  \relax{align}
  hold.  Degrees absent from the input or output spin space contribute zero.  These maps are realised by the column, row and full block of a kernel, respectively, with
  \relax{equation}
    u^\ell_n = (-1)^s a_\ell^{-1/2}\Psi^{\ell *}_{n,-s},\qquad
    v^\ell_k = (-1)^{s'}a_\ell^{1/2}\Psi^{\ell *}_{-s',k},\qquad
    B^\ell = \Psi^{\ell\dagger} .
    \relax{eq:classification-kernels}
  \relax{equation}
  Setting all unread entries to zero gives a canonical distributional kernel, which is square integrable if and only if the map is Hilbert--Schmidt.  The corresponding summability conditions are given in Appendix~\relax{app:proofs:classification}.
\relax{enumerate}

\relax{cor:nogo}
The kernel, in general a distribution, of a bounded equivariant map from one fixed input spin to one fixed output spin, $T : L^2_{s}(S^2) \to L^2_{s'}(S^2)$, is
\relax{equation}
  K(x,y) = (-1)^{s+s'} \sum_{\ell} c_\ell\, \frac{2\ell+1}{4\pi}\; D^{\ell}_{-s',-s}\big(s(x)^{-1}s(y)\big) ,
  \relax{eq:nogo-kernel}
\relax{equation}
a radial kernel with the frame phases forced by \eqref{eq:section-change}; for $s=s'=0$ it is $\sum_\ell c_\ell(2\ell+1)P_\ell(x\cdot y)/(4\pi)$.  Apart from the angular characters prescribed by the input and output spins, such a map cannot retain independent directional kernel content.  Thus, beyond the angular characters prescribed by the spins, directional kernels, a fixed-spin output on the sphere and equivariance cannot be achieved simultaneously for a fixed input spin.

\relax{prop:directional}
For $\prescript{}{s}{f}, \prescript{}{s}{\psi} \in L^2_{s}(S^2)$ (including $s = 0$),
\relax{equation}
  \prescript{}{s}{f} \circledast \prescript{}{s}{\psi} = \mathcal{C}_{s\to G}[\Lambda_{s}\psi]\; \prescript{}{s}{f},
  \qquad
  (\prescript{}{s}{f} \circledast \prescript{}{s}{\psi})^{\ell}_{mn} = \frac{8\pi^2}{2\ell+1}\; \prescript{}{s}{f}_{\ell m}\, \prescript{}{s}{\psi}^{*}_{\ell n} ,
\relax{equation}
exactly, with no residual constant.  The kernel $\Lambda_{s}\psi$ has Wigner support in the column $m' = -s$.

\relax{prop:synthesis}
For $W \in L^2(\mathrm{SO}(3))$ and $\prescript{}{s}{\psi} \in L^2_{s}(S^2)$,
\relax{gather}
  W \circledast^{\dagger} \prescript{}{s}{\psi} = \int_{\mathrm{SO}(3)} W(\rho)\, \big(\pi_{s}(\rho)\,\prescript{}{s}{\psi}\big) \,\mathrm{d}\mu(\rho) = \mathcal{C}_{G\to s}\big[\widetilde{\Lambda_{s}\psi}\big]\, W = \big(\mathcal{C}_{s\to G}[\Lambda_{s}\psi]\big)^{\dagger} W , \\
  (W \circledast^{\dagger} \prescript{}{s}{\psi})_{\ell m} = \sum_n W^{\ell}_{mn}\, \prescript{}{s}{\psi}_{\ell n} .
\relax{gather}
Synthesis is the adjoint of analysis, and the flipped kernel $\widetilde{\Lambda_{s}\psi}$ has Wigner support in the row $n = -s$.

\relax{prop:axisymmetric}
For axisymmetric $\psi$, $\psi_{\ell m} = \psi_{\ell 0}\delta_{m0}$,
\relax{equation}
  f \odot \psi = \frac{1}{\sqrt{2\pi}}\, \mathcal{C}_{0\to 0}[\Lambda_{0}\psi]\, f ,
  \qquad
  (f \odot \psi)_{\ell m} = \sqrt{\frac{4\pi}{2\ell+1}}\; f_{\ell m}\, \psi^{*}_{\ell 0} ,
\relax{equation}
and $\Lambda_{0}\psi$ satisfies the constraint \eqref{eq:two-sided} with $s = s' = 0$.  The same holds for the axisymmetric spin convolution of Definition~\relax{def:spin-axisymmetric}, which is $(2\pi)^{-1/2}\mathcal{C}_{s\to 0}[\Lambda_{s}\Phi]$ with harmonic form \eqref{eq:spin-axisymmetric-harmonic}.  For a non-axisymmetric $\psi$ the left-hand side is the standard correlation of Definition~\relax{def:standard-correlation}, which is not of the form $\mathcal{C}_{0\to 0}$ (Sec.~\relax{sec:beyond}).

\relax{prop:driscoll-healy}
For any $h \in L^2(S^2)$ let $\Psi_h(g) = h^{*}(g^{-1}\eta)$.  Then
\relax{equation}
  f \star_{\mathrm{L}} h = \mathcal{C}_{0\to 0}[\Psi_h]\, f ,
  \qquad
  (f \star_{\mathrm{L}} h)_{\ell m} = 2\pi \sqrt{\frac{4\pi}{2\ell+1}}\; f_{\ell m}\, h_{\ell 0} .
\relax{equation}
Only the entry $(\Psi_h)^{\ell}_{00}$ is read, so that only the zonal part of $h$ enters; the factor $2\pi$ is the fibre volume that appears because \eqref{eq:driscoll-healy} lifts $f$ and $h$ without the normalisation of Definition~\relax{def:lift}.  The marginalisation of the bilinear directional correlation over the third Euler angle used in \relax{kennedy2011azimuthally,esteves2018learning} is $\sqrt{2\pi}\,\Lambda_{0}^{\dagger}$.  Applied instead to the sesquilinear correlation of Definition~\relax{def:directional}, it conjugates the spherical kernel.

\relax{prop:spin-change}
Every bounded multiplier $\prescript{}{s'}{f}_{\ell m}=c_\ell\,\prescript{}{s}{f}_{\ell m}$, for $\ell\ge\max(\lvert s\rvert,\lvert s'\rvert)$ and annihilating input degrees absent from the target, is $\mathcal{C}_{s\to s'}[\Psi_T]$ in the Fourier-multiplier sense of Theorem~\relax{thm:classification}(b), with $\Psi_T{}^{\ell}_{-s',-s}=(-1)^{s+s'}c^{*}_{\ell}$.  The canonical kernel is generally a distribution and belongs to $L^2$ exactly when $\sum_\ell(2\ell+1)\lvert c_\ell\rvert^2<\infty$.  In particular:
\relax{enumerate}
  \item[(a)] the spin-weighted convolution of Esteves \mbox{\it et al.}\ \relax{esteves2020spin}, Eq.~(13), with a single input spin $s$ and output spin $s'$ has $c_\ell=\prescript{}{s'}{k}{}^{\ell}_{s}$ in their notation, and their multi-spin convolution sums over input spins and stacks output spins.  Their cross-correlation, Eq.~(15), $g^t_{\ell m}=\sum_i f^i_{\ell m}k^{i*}_{\ell t}$, instead corresponds to $\Psi^\ell_{-t,-i}=(-1)^{i+t}k^i_{\ell t}$;
  \item[(b)] the spin needlets of Geller \& Marinucci \relax{geller2010spin,geller2011mixed} are $\mathcal{C}_{s\to s}$ with $c_\ell = b\big(\sqrt{e_{\ell s}}/B^{j}\big)$, $e_{\ell s} = (\ell-\lvert s\rvert)(\ell+\lvert s\rvert+1)$, and their mixed needlets are the corresponding $\mathcal{C}_{s\to 0}$ and $\mathcal{C}_{0\to s}$; mixed needlets connect spin $s$ with spin $0$ only;
  \item[(c)] write $s(x)^{-1}s(y)=R_z(a)R_y(b)R_z(c)$.  In the translated canonical angles $(a,b,-c)$, the radial-with-phases construction of Tessore \mbox{\it et al.}\ \relax{tessore2025euclid} has kernel $e^{\mathrm{i} Sa}K(b)e^{\mathrm{i} sc}$, where $K(b)=\sum_\ell(2\ell+1)K_\ell d^\ell_{Ss}(b)/(4\pi)$, and is $\mathcal{C}_{s\to S}[\Psi_T]$ with $c_\ell=K_\ell$ by \eqref{eq:app-addition}.  The first angle differs by $\pi$ from the source's printed quadrant convention: its literal angles are $\alpha=a+\pi$, $\alpha'=-c$, giving $c_\ell=(-1)^S K_\ell$ in our conventions with the same radial coefficients;
  \item[(d)] the directional spin convolution of \relax{mcewen2015directional}, Definition~\relax{def:spin-directional}, is not itself of this form, its output being a function on $\mathrm{SO}(3)$, but for a steerable kernel, as the directional spin wavelets are, it is by Proposition~\relax{prop:band-limited} below the tuple of the spin-changing convolutions $\mathcal{C}_{s\to s'}[\Lambda_{s}\psi]$ over $\lvert s'\rvert < N$, with $c_\ell = (-1)^{s'}\sqrt{8\pi^2/(2\ell+1)}\;\prescript{}{s}{\psi}^{*}_{\ell,-s'}$ as in \eqref{eq:harmonic-ss-lifted}: the azimuthal order $-s'$ of the kernel is read to produce the output of spin $s'$, so that the directional spin convolution computes every spin-changing convolution of its kernel at once, and its axisymmetric case, the scaling coefficients of Definition~\relax{def:spin-axisymmetric}, is $(2\pi)^{-1/2}\mathcal{C}_{s\to 0}[\Lambda_{s}\Phi]$, with multiplier $c_\ell=\sqrt{4\pi/(2\ell+1)}\;\prescript{}{s}{\Phi}^{*}_{\ell0}$ as in Proposition~\relax{prop:axisymmetric}.
  \item[(e)] the spin spherical Fourier neural operator layer of the forthcoming article \relax{mulder2026spin}, which uses the same convention as here, learns the multiplier $c_\ell$ directly, as one harmonic weight per degree for each pair of spins $(s,s')$.
\relax{enumerate}

\relax{prop:band-limited}
If the column $m' = -s$ of $\Psi$ is supported on $\lvert n \rvert < N$ then
\relax{equation}
  \mathcal{C}_{s\to G}[\Psi] = \sum_{\lvert s'\rvert < N} \Lambda_{s'}\, \mathcal{C}_{s\to s'}[\Psi] ,
\relax{equation}
\mbox{\it i.e.}\ the output is represented by at most $2N-1$ spin-changing components $\mathcal{C}_{s\to s'}[\Psi]$, $\lvert s'\rvert<N$, with $2\min(\ell,N-1)+1$ admissible output slots at degree $\ell$.  Conversely, any finite tuple of bounded equivariant spin-changing maps from the same input spin assembles into a bounded map $\mathcal{C}_{s\to G}$ with a generally distributional kernel.  A square integrable representative exists exactly when the sum of their Hilbert--Schmidt norms squared is finite.  At finite band-limit the assembled kernel is always square integrable.

\relax{prop:physics}
The following classical operators have the multiplier form \eqref{eq:classification}, with \eqref{eq:multiplier-domain} understood for unbounded examples:
\relax{enumerate}
  \item[(a)] the spin raising operator $\eth : \mathcal{D}(\eth)\toL^2_{s+1}(S^2)$, with $c_\ell=\sqrt{(\ell-s)(\ell+s+1)}$, and the spin lowering operator $\bar\eth : \mathcal{D}(\bar\eth)\toL^2_{s-1}(S^2)$, with $c_\ell=-\sqrt{(\ell+s)(\ell-s+1)}$, have the first-order spin Sobolev domains $\mathcal{D}(\eth),\mathcal{D}(\bar\eth)\subsetL^2_{s}(S^2)$ specified by \eqref{eq:multiplier-domain} \relax{newman1966note,goldberg1967spin};
  \item[(b)] the $E$ and $B$ components of a spin-$\pm 2$ polarisation field, $a_{E,\ell m} = -\tfrac12(a_{2,\ell m}+a_{-2,\ell m})$ and $a_{B,\ell m} = \tfrac{\mathrm{i}}{2}(a_{2,\ell m}-a_{-2,\ell m})$ \relax{zaldarriaga1997all,kamionkowski1997statistics}, each the sum of a $\mathcal{C}_{2\to 0}$ and a $\mathcal{C}_{-2\to 0}$ operator with constant $c_\ell$; the scalars $\bar\eth^2(Q+\mathrm{i} U)$ and $\eth^2(Q-\mathrm{i} U)$ of \relax{zaldarriaga1997all} are the constituent $\mathcal{C}_{2\to 0}$ and $\mathcal{C}_{-2\to 0}$ maps with $c_\ell = \sqrt{(\ell+2)!/(\ell-2)!}$;
  \item[(c)] the spherical Kaiser--Squires relation of weak gravitational lensing between convergence and shear \relax{wallis2022mapping}: $\mathcal{C}_{0\to 2}$ with $c_\ell = \mathcal{D}_\ell = -\sqrt{(\ell+2)(\ell-1)/(\ell(\ell+1))}$ and its inverse $\mathcal{C}_{2\to 0}$ with $c_\ell = \mathcal{D}_\ell^{-1}$, for $\ell \ge 2$; the real-space forward map of \relax{wallis2022mapping} is synthesis with an axisymmetric spin-$2$ kernel, the adjoint of spin-$2$ to scalar analysis, rather than that forward analysis itself.  Its two-point kernel is \eqref{eq:nogo-kernel} with $(s,s')=(0,2)$;
  \item[(d)] the all-Stokes beam response of Challinor \mbox{\it et al.}\ \relax{challinor2000all}, \mbox{\it i.e.}\ their Eq.~(39), corresponds to a sum of $\mathcal{C}_{0\to G}$ maps on intensity $I$ and circular polarisation $V$, and $\mathcal{C}_{\pm2\to G}$ maps on linear polarisation.  For an axisymmetric co-polar beam, the intensity kernel has azimuthal order $0$ and the linear-polarisation kernels have the prescribed orders $\mp2$ for output spins $\pm2$.  Their Eqs.~(47)--(50) give scalar and spin-$2$ smoothing multipliers $W_\ell$ and $\prescript{}{2}{W}_\ell$; the response in Eq.~(46) depends on the third Euler angle through $\{1,\cos2\psi,\sin2\psi\}$, corresponding to the retained spins $0,\pm2$ and band-limit $N=3$ in Proposition~\relax{prop:band-limited}.
\relax{enumerate}

\relax{prop:section-evaluation}
Let $\sigma(x)=s(x)R_z(\chi_\sigma(x))$ be a measurable section and let $\Psi\inL^2(\mathrm{SO}(3))$ satisfy $\Psi^\ell_{n,-s}=0$ for $\lvert n\rvert\ge N$.  Define $E_\sigma[\Psi]\,\prescript{}{s}{f}=(\Psi\star\Lambda_{s}\,\prescript{}{s}{f})\circ\sigma$, using the continuous representative of the $L^2*L^2$ correlation.  Then
\relax{equation}
  E_\sigma[\Psi]\, \prescript{}{s}{f} = \sum_{\lvert s'\rvert < N} \frac{e^{-\mathrm{i} s'\chi_\sigma}}{\sqrt{2\pi}}\; \mathcal{C}_{s\to s'}[\Psi]\, \prescript{}{s}{f} ,
  \relax{eq:section-evaluation}
\relax{equation}
where $N$ bounds the first index within the effective input column.  With the fixed coordinate-frame output action, the zero map is equivariant into every spin space for every section.  Otherwise $E_\sigma[\Psi]$ is equivariant into spin-$t$ fields if and only if $\Psi^\ell_{n,-s}=0$ for $n\ne-t$ and $e^{-\mathrm{i} t\chi_\sigma}$ is constant almost everywhere.  The latter condition is automatic for $t=0$.

For $\sigma_0=s(\cdot)$, all polar rotations are symmetries.  For $\chi_\sigma=\pi-\varphi$, a polar rotation $R_z(a)$ is a symmetry exactly when $e^{\mathrm{i} ta}=1$ for every active output spin $t$, where active means $\Psi^\ell_{-t,-s}\ne0$ for some $\ell$.  This criterion does not classify non-polar symmetries.

Inserting $s(g_2x)\,s(g_2x)^{-1}$ into the definition \eqref{eq:twist} and regrouping,
\relax{align}
  \hbar(x,g_1g_2) &= s(g_1g_2x)^{-1}\,g_1g_2\,s(x) \notag\\
  &= \big[s(g_1g_2x)^{-1}\,g_1\,s(g_2x)\big]\big[s(g_2x)^{-1}\,g_2\,s(x)\big]
  = \hbar(g_2x,g_1)\,\hbar(x,g_2) ,
\relax{align}
where the first bracket is the twist of $g_1$ at the point $g_2x$ and the second the twist of $g_2$ at $x$.  On the sphere, for $0<\beta<\pi$, the rotation $R(\alpha,\beta,\gamma)$ sends the North pole to the point $(\beta,\alpha)$, so that $s(R(\alpha,\beta,\gamma)\eta) = R(\alpha,\beta,0)$ and
\relax{equation}
  \hbar(R(\alpha,\beta,\gamma)) = R(\alpha,\beta,0)^{-1}R(\alpha,\beta,\gamma) = R_y(\beta)^{-1}R_z(\alpha)^{-1}R_z(\alpha)R_y(\beta)R_z(\gamma) = R_z(\gamma) ,
\relax{equation}
as claimed.  At $\beta=0$, the choice $s(\eta)=e$ instead gives $\hbar(R(\alpha,0,\gamma))=R_z(\alpha+\gamma)$; at $\beta=\pi$, the choice $s(-\eta)=R_y(\pi)$ gives $R_z(\gamma-\alpha)$.  These endpoint choices do not affect any $L^2$ identity.

(a) By Fubini's theorem, $\lVert\Lambda_{s}f\rVert^2 = \frac{1}{2\pi}\int_0^{2\pi}\,\mathrm{d}\gamma\int_{S^2}\lvert f\rvert^2\,\mathrm{d}\mu = \lVert f\rVert^2$, so that $\Lambda_{s}$ is an isometry, and
\relax{align}
  \langle\Lambda_{s}f, F\rangle &= \int_{S^2}\,\mathrm{d}\mu(\beta,\alpha)\, f(\beta,\alpha)\,\Big[\frac{1}{\sqrt{2\pi}}\int_0^{2\pi}e^{\mathrm{i} s\gamma}F(\alpha,\beta,\gamma)\,\mathrm{d}\gamma\Big]^{*} \notag\\
  &= \langle f, \Lambda_{s}^{\dagger}F\rangle
\relax{align}
identifies \eqref{eq:lift-proj} as the adjoint.  Next, $\Lambda_{s}^{\dagger}\Lambda_{s}f = f$ since $\frac{1}{2\pi}\int_0^{2\pi}e^{\mathrm{i} s\gamma}e^{-\mathrm{i} s\gamma}\,\mathrm{d}\gamma = 1$.  Since $R(\alpha,\beta,\gamma)R_z(\gamma') = R(\alpha,\beta,\gamma+\gamma')$, the lift $\Lambda_{s}f$ satisfies \eqref{eq:Ms}; conversely, $F \in \mathcal{M}_{s}$ has a fibrewise equivariant representative with $F(\alpha,\beta,\gamma) = e^{-\mathrm{i} s\gamma}F(\alpha,\beta,0)$ for almost every $(\alpha,\beta,\gamma)$, so that $F = \Lambda_{s}(\sqrt{2\pi}\,F\circ s)$ with $\sqrt{2\pi}\,F\circ s \in L^2(S^2)$ by Fubini's theorem, and the range of $\Lambda_{s}$ is all of $\mathcal{M}_{s}$.  Finally,
\relax{equation}
  (\Lambda_{s}\Lambda_{s}^{\dagger}F)(\alpha,\beta,\gamma) = e^{-\mathrm{i} s\gamma}\,\frac{1}{2\pi}\int_0^{2\pi}e^{\mathrm{i} s\gamma'}F(\alpha,\beta,\gamma')\,\mathrm{d}\gamma'
\relax{equation}
is the term in $e^{-\mathrm{i} s\gamma}$ of the Fourier series of $F(\alpha,\beta,\cdot)$ in $\gamma$, which for almost every $(\alpha,\beta)$ is a square integrable function on the circle.  Hence $\Lambda_{s}\Lambda_{s}^{\dagger}$ is the orthogonal projector onto $\mathcal{M}_{s}$, the subspaces $\mathcal{M}_{s}$ are mutually orthogonal, and $\sum_s\Lambda_{s}\Lambda_{s}^{\dagger}F = F$ in $L^2(\mathrm{SO}(3))$ by Plancherel's theorem on the circle and Fubini's theorem, which is the decomposition $L^2(\mathrm{SO}(3)) = \widehat{\bigoplus}_s\mathcal{M}_{s}$.

(b) Using the fibrewise equivariant representative of $F \in \mathcal{M}_{s}$,
\relax{align*}
  (\Lambda_{s}^{\dagger}F)(\beta,\alpha)
  &= \frac{1}{\sqrt{2\pi}}\int_0^{2\pi}e^{\mathrm{i} s\gamma}e^{-\mathrm{i} s\gamma}F(\alpha,\beta,0)\,\mathrm{d}\gamma \\
  &= \sqrt{2\pi}\,F(\alpha,\beta,0).
\relax{align*}

(d) By \eqref{eq:sY-D}, $\Lambda_{s}\prescript{}{s}{Y}_{\ell m} = (2\pi)^{-1/2}e^{-\mathrm{i} s\gamma}\prescript{}{s}{Y}_{\ell m}(\beta,\alpha) = (-1)^s\sqrt{(2\ell+1)/8\pi^2}\;D^{\ell *}_{m,-s}$, which has unit norm by the orthogonality relation of the Wigner $D$-functions.

(c) By (d) and the orthogonality relation, the Wigner coefficients of $\Lambda_{s}\prescript{}{s}{Y}_{\ell m}$ are $\int\Lambda_{s}\prescript{}{s}{Y}_{\ell m}\,D^{\ell'}_{m'n'}\,\mathrm{d}\mu = (-1)^s\sqrt{8\pi^2/(2\ell+1)}\,\delta_{\ell\ell'}\delta_{mm'}\delta_{n',-s}$, and the first relation of \eqref{eq:lift-harmonic} follows by linearity and the continuity of $\Lambda_{s}$.  For the projection, $(\Lambda_{s}^{\dagger}F)_{\ell m} = \langle\Lambda_{s}^{\dagger}F,\prescript{}{s}{Y}_{\ell m}\rangle = \langle F,\Lambda_{s}\prescript{}{s}{Y}_{\ell m}\rangle = (-1)^s\sqrt{(2\ell+1)/8\pi^2}\int F\,D^{\ell}_{m,-s}\,\mathrm{d}\mu$, which is the second relation.

(e) This is Proposition~\relax{prop:intertwining}, proved next.

Since $(\pi_{G}(g)F)(g'h) = F(g^{-1}g'h) = \rho^{(s)}(h^{-1})(\pi_{G}(g)F)(g')$ for $F \in \mathcal{M}_{s}$, the left regular representation preserves $\mathcal{M}_{s}$, and $\pi_{s}(g) = \Lambda_{s}^{\dagger}\pi_{G}(g)\Lambda_{s}$ is therefore a representation: by Lemma~\relax{lem:lift}(a), $\pi_{s}(g)\pi_{s}(g') = \Lambda_{s}^{\dagger}\pi_{G}(g)\,\Lambda_{s}\Lambda_{s}^{\dagger}\,\pi_{G}(g')\Lambda_{s} = \Lambda_{s}^{\dagger}\pi_{G}(g)\pi_{G}(g')\Lambda_{s} = \pi_{s}(gg')$, since $\Lambda_{s}\Lambda_{s}^{\dagger}$ is the identity on the range of $\pi_{G}(g')\Lambda_{s}$, which lies in $\mathcal{M}_{s}$.  It is unitary since $\pi_{s}(g)^{\dagger} = \Lambda_{s}^{\dagger}\pi_{G}(g)^{\dagger}\Lambda_{s} = \Lambda_{s}^{\dagger}\pi_{G}(g^{-1})\Lambda_{s} = \pi_{s}(g^{-1})$, and it intertwines, $\Lambda_{s}\pi_{s}(g) = \Lambda_{s}\Lambda_{s}^{\dagger}\pi_{G}(g)\Lambda_{s} = \pi_{G}(g)\Lambda_{s}$, again because $\pi_{G}(g)\Lambda_{s}f \in \mathcal{M}_{s}$; taking adjoints gives $\pi_{s}(g)\Lambda_{s}^{\dagger} = \Lambda_{s}^{\dagger}\pi_{G}(g)$.

For the explicit form, write $(\Lambda_{s}f)(g) = (2\pi)^{-1/2}\rho^{(s)}(\hbar(g)^{-1})f(gH)$ with $\hbar(g) = s(gH)^{-1}g$, which is Definition~\relax{def:lift} by Lemma~\relax{lem:twist-composition}.  Since $\pi_{G}(g)\Lambda_{s}f \in \mathcal{M}_{s}$, Lemma~\relax{lem:lift}(b) gives
\relax{equation}
  (\pi_{s}(g)f)(x) = \sqrt{2\pi}\,(\Lambda_{s}f)(g^{-1}s(x)) = \rho^{(s)}\big(\hbar(g^{-1}s(x))^{-1}\big)\,f(g^{-1}x),
\relax{equation}
and $\hbar(g^{-1}s(x)) = s(g^{-1}x)^{-1}g^{-1}s(x) = \hbar(x,g^{-1})$ by \eqref{eq:twist}, which is \eqref{eq:induced-explicit}.  The same conclusion follows from Lemma~\relax{lem:twist-composition} with $x = x_0$, $g_1 = g^{-1}$ and $g_2 = g'$, which splits $\hbar(g^{-1}g')$ into $\hbar(g'H,g^{-1})\,\hbar(g')$.

On the sphere, away from the coordinate singularities, with $g = R_\rho$ and $x = \omega$, the rotation $R_\rho^{-1}R_\omega$ sends the North pole to $R_\rho^{-1}\omega$, so that its Euler angles are $(\alpha',\beta',\vartheta)$ with $(\beta',\alpha') = R_\rho^{-1}\omega$, \mbox{\it i.e.}\ $R_\rho^{-1}R_\omega = R(\alpha',\beta',0)R_z(\vartheta) = s(R_\rho^{-1}\omega)R_z(\vartheta)$.  Hence $\hbar(\omega,R_\rho^{-1}) = s(R_\rho^{-1}\omega)^{-1}R_\rho^{-1}s(\omega) = R_z(\vartheta)$, and \eqref{eq:induced-explicit} reads $(\pi_{s}(R_\rho)f)(\omega) = e^{-\mathrm{i} s\vartheta}f(R_\rho^{-1}\omega)$, which is \eqref{eq:spin-rotation}.

Finally, \eqref{eq:rotation-coeffs} follows by lifting: by Lemma~\relax{lem:lift}(c) and the action of left translation on the first Wigner index,
\relax{align}
  (\pi_{s}(\rho)f)_{\ell m} &= (-1)^s\sqrt{\tfrac{2\ell+1}{8\pi^2}}\,\big(\pi_{G}(\rho)\Lambda_{s}f\big)^{\ell}_{m,-s}
  = (-1)^s\sqrt{\tfrac{2\ell+1}{8\pi^2}}\sum_{m'}D^{\ell}_{mm'}(\rho)\,(\Lambda_{s}f)^{\ell}_{m',-s} \notag\\
  &= \sum_{m'}D^{\ell}_{mm'}(\rho)\,\prescript{}{s}{f}_{\ell m'} ,
\relax{align}
the constants cancelling, which holds with the same matrices $D^{\ell}(\rho)$ for every spin.

Substituting $\rho = \rho' h^{-1}$, \mbox{\it i.e.}\ $h = \rho^{-1}\rho'$, in the Wigner transform of \eqref{eq:group-conv}, which is permitted since the Haar measure is bi-invariant, and expanding $D^{\ell}_{mn}(\rho'h^{-1}) = \sum_k D^{\ell}_{mk}(\rho')\,D^{\ell *}_{nk}(h)$ by the representation property and unitarity,
\relax{align}
  (\Psi\star F)^{\ell}_{mn}
  &= \int_{\mathrm{SO}(3)}\!\!\int_{\mathrm{SO}(3)} \Psi^{*}(h)\,F(\rho')\,D^{\ell}_{mn}(\rho'h^{-1})\,\mathrm{d}\mu(h)\,\mathrm{d}\mu(\rho') \notag\\
  &= \sum_k \Big[\int_{\mathrm{SO}(3)} F(\rho')D^{\ell}_{mk}(\rho')\,\mathrm{d}\mu(\rho')\Big]\Big[\int_{\mathrm{SO}(3)}\Psi^{*}(h)\,D^{\ell *}_{nk}(h)\,\mathrm{d}\mu(h)\Big]
  = \sum_k F^{\ell}_{mk}\,\Psi^{\ell *}_{nk} ,
\relax{align}
where the interchange of integrals is justified by Fubini's theorem since $\Psi, F \in L^2(\mathrm{SO}(3)) \subset L^1(\mathrm{SO}(3))$.  For equivariance,
\relax{align}
  (\Psi\star\pi_{G}(g)F)(\rho) &= \int\Psi^{*}(\rho^{-1}\rho')\,F(g^{-1}\rho')\,\mathrm{d}\mu(\rho') \notag\\
  &= \int\Psi^{*}(\rho^{-1}g\rho'')\,F(\rho'')\,\mathrm{d}\mu(\rho'') = (\Psi\star F)(g^{-1}\rho) .
\relax{align}
For boundedness, in the notation $F^{\ell}$ for the $(2\ell+1)\times(2\ell+1)$ block of coefficients, \eqref{eq:group-conv-harmonic} reads $(\Psi\star F)^{\ell} = F^{\ell}\Psi^{\ell\dagger}$, hence by Parseval's identity $\lVert\Psi\star F\rVert^2 = \sum_\ell\frac{2\ell+1}{8\pi^2}\lVert F^{\ell}\Psi^{\ell\dagger}\rVert_{\mathrm{F}}^2 \le \sup_\ell\lVert\Psi^{\ell}\rVert^2_{\mathrm{op}}\,\lVert F\rVert^2$, and $\lVert\Psi^{\ell}\rVert^2_{\mathrm{op}} \le \lVert\Psi^{\ell}\rVert^2_{\mathrm{F}} \le \frac{8\pi^2}{2\ell+1}\lVert\Psi\rVert^2$, where $\lVert\cdot\rVert_{\mathrm{F}}$ denotes the Frobenius norm.  For the adjoint, by Fubini's theorem
\relax{equation}
  \langle\Psi\star F, G\rangle = \int_{\mathrm{SO}(3)} F(g')\,\Big[\int_{\mathrm{SO}(3)}\Psi(g^{-1}g')\,G(g)\,\mathrm{d}\mu(g)\Big]^{*}\,\mathrm{d}\mu(g') ,
\relax{equation}
and $\int\Psi(g^{-1}g')G(g)\,\mathrm{d}\mu(g) = \int\widetilde\Psi^{*}(g'^{-1}g)\,G(g)\,\mathrm{d}\mu(g) = (\widetilde\Psi\star G)(g')$ with $\widetilde\Psi(k) = \Psi^{*}(k^{-1})$, so that $(\Psi\star)^{\dagger} = \widetilde\Psi\star$.  As a check, the Wigner coefficients of the flipped kernel are $\widetilde\Psi^{\ell}_{mn} = \int\Psi^{*}(g^{-1})D^{\ell}_{mn}(g)\,\mathrm{d}\mu(g) = \int\Psi^{*}(g)\,D^{\ell *}_{nm}(g)\,\mathrm{d}\mu(g) = \Psi^{\ell *}_{nm}$, \mbox{\it i.e.}\ $\widetilde\Psi^{\ell} = \Psi^{\ell\dagger}$, and $(\widetilde\Psi\star G)^{\ell} = G^{\ell}\Psi^{\ell}$ is indeed the adjoint of $F^{\ell} \mapsto F^{\ell}\Psi^{\ell\dagger}$ with respect to the Frobenius inner product.

By \eqref{eq:lift-harmonic}, $(\Lambda_{s}\prescript{}{s}{f})^{\ell}_{mm'} = (-1)^s\sqrt{8\pi^2/(2\ell+1)}\,\prescript{}{s}{f}_{\ell m}\delta_{m',-s}$, so that the sum over $m'$ in \eqref{eq:group-conv-harmonic} collapses to the single term $m' = -s$, which gives \eqref{eq:harmonic-sG}.  Applying $\Lambda_{s'}^{\dagger}$ by \eqref{eq:lift-harmonic} reads the column $n = -s'$ and multiplies by $(-1)^{s'}\sqrt{(2\ell+1)/8\pi^2}$, so that the degree-dependent constants cancel and \eqref{eq:harmonic-ss} follows; \eqref{eq:harmonic-Gs} is $\Lambda_{s'}^{\dagger}$ applied to \eqref{eq:group-conv-harmonic}, and \eqref{eq:harmonic-GG} is \eqref{eq:group-conv-harmonic} itself.  Degrees $\ell < \lvert s\rvert$ are absent from $L^2_{s}(S^2)$ and degrees $\ell < \lvert s'\rvert$ from $L^2_{s'}(S^2)$, whence the restriction on $\ell$.  Boundedness follows from that of $\Lambda_{s}$, $\Lambda_{s'}^{\dagger}$ and $\Psi\star$.  For equivariance,
\relax{align}
  \mathcal{C}_{s\to s'}[\Psi]\,\pi_{s}(g) &= \Lambda_{s'}^{\dagger}\big(\Psi\star\Lambda_{s}\pi_{s}(g)\,\cdot\big) = \Lambda_{s'}^{\dagger}\big(\Psi\star\pi_{G}(g)\Lambda_{s}\,\cdot\big) \notag\\
  &= \Lambda_{s'}^{\dagger}\pi_{G}(g)\big(\Psi\star\Lambda_{s}\,\cdot\big) = \pi_{s'}(g)\,\mathcal{C}_{s\to s'}[\Psi]
\relax{align}
by Lemma~\relax{lem:lift}(e) and the equivariance of $\Psi\star$; the other three cases drop the lift, the projection, or both.  The adjoint identities follow from $(\Psi\star)^{\dagger} = \widetilde\Psi\star$ and $(\Lambda_{s})^{\dagger} = \Lambda_{s}^{\dagger}$: for instance $(\mathcal{C}_{s\to G}[\Psi])^{\dagger} = (\Psi\star\Lambda_{s})^{\dagger} = \Lambda_{s}^{\dagger}\,\widetilde\Psi\star = \mathcal{C}_{G\to s}[\widetilde\Psi]$.

By Lemma~\relax{lem:lift}(a) and (c), a function on $\mathrm{SO}(3)$ lies in $\mathcal{M}_{s'}$ if and only if its Wigner coefficients vanish outside the column $n = -s'$.  By \eqref{eq:harmonic-sG}, the coefficients of $\Psi\star\Lambda_{s}f$ are $(-1)^s\sqrt{8\pi^2/(2\ell+1)}\,\prescript{}{s}{f}_{\ell m}\,\Psi^{\ell *}_{n,-s}$, which vanish for all $n \ne -s'$ and all $f$ if and only if $\Psi^{\ell}_{n,-s} = 0$ for all $n \ne -s'$ and all $\ell \ge \lvert s\rvert$, as is seen by taking $f = \prescript{}{s}{Y}_{\ell m}$; this is the equivalence of (i) and (ii).  For (iii), the Wigner coefficients of the right-isotypic part are
\relax{align}
  \big(\Psi^{(s)}\big)^{\ell}_{nm'} &= \frac{1}{2\pi}\int_0^{2\pi}e^{\mathrm{i} s\gamma}\int_{\mathrm{SO}(3)}\Psi(gR_z(\gamma))\,D^{\ell}_{nm'}(g)\,\mathrm{d}\mu(g)\,\mathrm{d}\gamma \notag\\
  &= \frac{1}{2\pi}\int_0^{2\pi}e^{\mathrm{i}(s+m')\gamma}\,\mathrm{d}\gamma\;\Psi^{\ell}_{nm'} = \delta_{m',-s}\,\Psi^{\ell}_{nm'} ,
\relax{align}
by the substitution $g' = gR_z(\gamma)$ and $D^{\ell}_{nm'}(g'R_z(-\gamma)) = D^{\ell}_{nm'}(g')e^{\mathrm{i} m'\gamma}$: the right-isotypic part is the column $m' = -s$ of $\Psi$, which is exactly the part read by \eqref{eq:harmonic-sG}.  Since $D^{\ell *}_{nm'}(R_z(\chi_1)gR_z(\chi_2)) = e^{\mathrm{i} n\chi_1}\,D^{\ell *}_{nm'}(g)\,e^{\mathrm{i} m'\chi_2}$, the Wigner expansion of $\Psi^{(s)}$ satisfies \eqref{eq:two-sided} if and only if its coefficients vanish unless $n = -s'$ and $m' = -s$, which is (ii).  In that case $\Psi\star\Lambda_{s}f \in \mathcal{M}_{s'}$ and Lemma~\relax{lem:lift}(b) gives $\mathcal{C}_{s\to s'}[\Psi]f = \sqrt{2\pi}\,(\Psi\star\Lambda_{s}f)\circ s$; the Wigner expansion \eqref{eq:wigner-transform} restricted to the entry $(-s',-s)$, with $D^{\ell *}_{-s',-s}(\alpha,\beta,\gamma) = e^{-\mathrm{i} s'\alpha}d^{\ell}_{-s',-s}(\beta)e^{-\mathrm{i} s\gamma}$, is \eqref{eq:constrained-kernel}.  Finally, for any $\Psi=\Lambda_{s}\psi$, \eqref{eq:lift-harmonic} gives $\Psi^{\ell}_{-s',-s} = (-1)^s\sqrt{8\pi^2/(2\ell+1)}\,\prescript{}{s}{\psi}_{\ell,-s'}$, and substituting into \eqref{eq:harmonic-ss} yields \eqref{eq:harmonic-ss-lifted}.

By Lemma~\relax{lem:lift}(a) and (d), $\Lambda_{s}$ is a unitary equivalence between $L^2_{s}(S^2)$ and $\mathcal{M}_{s} = \widehat{\bigoplus}_{\ell\ge\lvert s\rvert}V^{(s)}_\ell$, where $V^{(s)}_\ell = \mathrm{span}\{D^{\ell *}_{m,-s} : \lvert m\rvert\le\ell\}$ is the image of the degree-$\ell$ spin harmonics, and by the action of left translation on the first Wigner index, $\pi_{G}(\rho)\,D^{\ell *}_{m,-s} = \sum_k D^{\ell}_{km}(\rho)\,D^{\ell *}_{k,-s}$, so that each $V^{(s)}_\ell$ is invariant and carries the irreducible representation of $\mathrm{SO}(3)$ of degree $\ell$, in the same matrices for every $s$; this is \eqref{eq:rotation-coeffs}.  Thus $L^2_{s}(S^2)$ decomposes into irreducible representations without multiplicity, each degree $\ell \ge \lvert s\rvert$ occurring exactly once.  This is Frobenius reciprocity \relax{mackey1952induced,folland2016course} in the present case: the multiplicity of the degree-$\ell$ representation in $\operatorname{Ind}_{\mathrm{SO}(2)}^{\mathrm{SO}(3)}\rho^{(s)}$ equals the multiplicity of $\rho^{(s)}$ in the restriction of the degree-$\ell$ representation to $\mathrm{SO}(2)$, which is one for $\lvert s\rvert \le \ell$ and zero otherwise since $D^{\ell}_{mn}(R_z(\gamma)) = e^{-\mathrm{i} n\gamma}\delta_{mn}$ contains each character with $\lvert n\rvert \le \ell$ exactly once.

Let $T$ be bounded and equivariant.  Since irreducible representations of different degree are inequivalent, $T$ maps the degree-$\ell$ component of $L^2_{s}(S^2)$ into the degree-$\ell$ component of $L^2_{s'}(S^2)$, and annihilates it if $\ell < \lvert s'\rvert$.  For $\ell \ge \max(\lvert s\rvert,\lvert s'\rvert)$ the two components are equivalent irreducible representations, realised in the bases $\prescript{}{s}{Y}_{\ell m}$ and $\prescript{}{s'}{Y}_{\ell m}$ by the same matrices $D^{\ell}(\rho)$, so that by Schur's lemma the restriction of $T$ is a scalar $c_\ell$ times the identity in these bases, which is \eqref{eq:classification}; the sequence is unique, and $\lVert T\rVert = \sup_\ell\lvert c_\ell\rvert$ by Parseval's identity, so that $T$ is bounded if and only if the sequence is.  Conversely, a bounded sequence defines a bounded $T$ by \eqref{eq:classification}, which commutes with $\pi_{s}$ by \eqref{eq:rotation-coeffs}.

(a) If $T = \mathcal{C}_{s\to s'}[\Psi]$ with $\Psi \in L^2(\mathrm{SO}(3))$, then $c_\ell = (-1)^{s+s'}\Psi^{\ell *}_{-s',-s}$ by \eqref{eq:harmonic-ss}, and $\sum_\ell\frac{2\ell+1}{8\pi^2}\lvert c_\ell\rvert^2 \le \lVert\Psi\rVert^2 < \infty$ by Parseval's identity.  Conversely, if $\sum_\ell(2\ell+1)\lvert c_\ell\rvert^2 < \infty$, the function $\Psi_T$ with Wigner coefficients $\Psi_T{}^{\ell}_{-s',-s} = (-1)^{s+s'}c^{*}_{\ell}$ and all others zero lies in $L^2(\mathrm{SO}(3))$, with $\lVert\Psi_T\rVert^2 = \sum_\ell\frac{2\ell+1}{8\pi^2}\lvert c_\ell\rvert^2$, and $\mathcal{C}_{s\to s'}[\Psi_T] = T$ by \eqref{eq:harmonic-ss}.  Since the Hilbert--Schmidt norm of $T$ is $\lVert T\rVert^2_{\mathrm{HS}} = \sum_{\ell m}\lvert c_\ell\rvert^2 = \sum_\ell(2\ell+1)\lvert c_\ell\rvert^2$, the condition is that $T$ be Hilbert--Schmidt.  Any $\Psi$ with $\mathcal{C}_{s\to s'}[\Psi] = T$ has the same entries $\Psi^{\ell}_{-s',-s}$, all other entries being unread, and $\Psi_T$ is the unique such kernel whose entire Wigner block is supported on that entry, equivalently whose entire kernel satisfies the two-sided law of \eqref{eq:two-sided}.  Constraining only $\Psi^{(s)}$ would still permit arbitrary unread input columns and would not give uniqueness.

(b) For a bounded sequence, $\Psi_T$ is a distribution on $\mathrm{SO}(3)$ with bounded Wigner coefficients, and $\mathcal{C}_{s\to s'}[\Psi_T]$ is defined by \eqref{eq:harmonic-ss} on the dense subspace of band-limited fields, on which it coincides with $T$; since $\lvert c_\ell\rvert$ is bounded it extends by continuity to $L^2_{s}(S^2)$, and the extension is $T$.  This is the sense in which every bounded equivariant map is a lifted convolution with a distributional kernel.

(c) The left regular representation decomposes as $L^2(\mathrm{SO}(3)) = \widehat{\bigoplus}_\ell\bigoplus_{\lvert n\rvert\le\ell}V_\ell^{(n)}$, with $V^{(n)}_\ell = \mathrm{span}\{D^{\ell *}_{mn} : \lvert m\rvert\le\ell\}$ the $n$-th Wigner column, each column carrying the degree-$\ell$ representation in the same matrices; the degree-$\ell$ representation thus occurs with multiplicity $2\ell+1$, one copy per column.  Schur's lemma gives a vector of coefficients $u^\ell$ from a spin field into the Wigner columns, a vector $v^\ell$ from those columns into a spin field, and an arbitrary matrix $B^\ell$ acting on the multiplicity index for a group-to-group map, as in \eqref{eq:classification-blocks}.  Conversely these coefficient maps commute degree by degree with the action on the first index.  For the first case Parseval's identity gives
\relax{equation}
  \lVert T_{s\to G}f\rVert^2
  = \sum_{\ell\ge\lvert s\rvert} a_\ell\lVert u^\ell\rVert_2^2\sum_m\lvert\prescript{}{s}{f}_{\ell m}\rvert^2 .
\relax{equation}
For the second, Cauchy--Schwarz gives
\relax{equation}
  \lVert T_{G\to s'}F\rVert^2
  \le \sup_{\ell\ge\lvert s'\rvert}\frac{\lVert v^\ell\rVert_2^2}{a_\ell}
  \sum_\ell a_\ell\lVert F^\ell\rVert_{\mathrm{F}}^2 ,
\relax{equation}
with equality on a single row of a single block proportional to $(v^\ell)^*$; taking degrees approaching the supremum gives the exact norm.  Similarly, $\lVert F^\ell B^\ell\rVert_{\mathrm{F}}\le\lVert F^\ell\rVert_{\mathrm{F}}\lVert B^\ell\rVert_{\mathrm{op}}$, with equality attained on a suitable row, gives the third norm in \eqref{eq:classification-norms}.  Thus those uniform bounds are necessary and sufficient for extension from finite harmonic sums to the Hilbert direct sums; entrywise bounds alone do not suffice.

Comparing with Theorem~\relax{thm:harmonic} gives \eqref{eq:classification-kernels}.  The norm bounds make the canonical kernel blocks uniformly bounded in operator norm, and hence define distributions.  Summing the squared images of orthonormal bases, with the factor $a_\ell^{-1/2}$ for a unit-norm Wigner coefficient, gives
\relax{align}
  \lVert T_{s\to s'}\rVert_{\mathrm{HS}}^2 &= \sum_\ell d_\ell\lvert c_\ell\rvert^2, &
  \lVert T_{s\to G}\rVert_{\mathrm{HS}}^2 &= \sum_\ell d_\ell a_\ell\lVert u^\ell\rVert_2^2, \notag\\
  \lVert T_{G\to s'}\rVert_{\mathrm{HS}}^2 &= \sum_\ell \frac{d_\ell}{a_\ell}\lVert v^\ell\rVert_2^2, &
  \lVert T_{G\to G}\rVert_{\mathrm{HS}}^2 &= \sum_\ell d_\ell\lVert B^\ell\rVert_{\mathrm{F}}^2 .
  \relax{eq:classification-hs}
\relax{align}
Each sum is over the degrees present in both spaces.  By Parseval's identity each is $8\pi^2\lVert\Psi_T\rVert^2$ for the canonical kernel with unread entries set to zero, so a square integrable representative exists exactly when the map is Hilbert--Schmidt.  Adding unread coefficients cannot remove a divergence in the canonical part.

By \eqref{eq:classification},
\relax{align}
  (Tf)(x) &= \sum_\ell c_\ell\sum_m\prescript{}{s'}{Y}_{\ell m}(x)\,\langle f,\prescript{}{s}{Y}_{\ell m}\rangle = \int_{S^2}K(x,y)\,f(y)\,\mathrm{d}\mu(y), \notag\\
  K(x,y) &= \sum_\ell c_\ell\sum_m\prescript{}{s'}{Y}_{\ell m}(x)\,\prescript{}{s}{Y}^{*}_{\ell m}(y) ,
\relax{align}
the series converging in the sense of distributions.  By \eqref{eq:sY-D} at $\gamma = 0$, $\prescript{}{s'}{Y}_{\ell m}(x) = (-1)^{s'}\sqrt{(2\ell+1)/4\pi}\,D^{\ell *}_{m,-s'}(s(x))$ and $\prescript{}{s}{Y}^{*}_{\ell m}(y) = (-1)^{s}\sqrt{(2\ell+1)/4\pi}\,D^{\ell}_{m,-s}(s(y))$, so that, by $D^{\ell *}_{mn}(g) = D^{\ell}_{nm}(g^{-1})$ and the representation property,
\relax{align}
  \sum_m\prescript{}{s'}{Y}_{\ell m}(x)\,\prescript{}{s}{Y}^{*}_{\ell m}(y) &= (-1)^{s+s'}\frac{2\ell+1}{4\pi}\sum_m D^{\ell}_{-s',m}\big(s(x)^{-1}\big)\,D^{\ell}_{m,-s}\big(s(y)\big) \notag\\
  &= (-1)^{s+s'}\frac{2\ell+1}{4\pi}\,D^{\ell}_{-s',-s}\big(s(x)^{-1}s(y)\big) ,
\relax{align}
which is the addition theorem for spin spherical harmonics and gives \eqref{eq:nogo-kernel}.  The rotation $s(x)^{-1}s(y)$ sends the North pole to $s(x)^{-1}y$, the point $y$ expressed in the frame of $x$, whose colatitude is the geodesic distance $\beta_{xy}$ between $x$ and $y$; writing its Euler angles as $(\alpha_{xy},\beta_{xy},\gamma_{xy})$, the kernel reads $D^{\ell}_{-s',-s}(\alpha_{xy},\beta_{xy},\gamma_{xy}) = e^{\mathrm{i} s'\alpha_{xy}}\,d^{\ell}_{-s',-s}(\beta_{xy})\,e^{\mathrm{i} s\gamma_{xy}}$, in which only the $d$-function depends on the distance and the two exponentials are the phases of a kernel with output spin $s'$ in $x$ and dual input spin $-s$ in $y$: under a frame change, $K'(x,y)=e^{-\mathrm{i} s'\chi(x)}K(x,y)e^{+\mathrm{i} s\chi(y)}$ by \eqref{eq:section-change}.  For $s = s' = 0$, $d^{\ell}_{00}(\beta) = P_\ell(\cos\beta)$ and $\cos\beta_{xy} = x\cdot y$.

Since $\pi_{s}(\rho)\psi = \Lambda_{s}^{\dagger}\pi_{G}(\rho)\Lambda_{s}\psi$ and $\Lambda_{s}^{\dagger}$ is bounded,
\relax{equation}
  \int_{\mathrm{SO}(3)} W(\rho)\,\pi_{s}(\rho)\psi\,\mathrm{d}\mu(\rho) = \Lambda_{s}^{\dagger}\int_{\mathrm{SO}(3)} W(\rho)\,\pi_{G}(\rho)\Phi\,\mathrm{d}\mu(\rho),
\relax{equation}
where $\Phi = \Lambda_{s}\psi$ and
the integrals are Bochner integrals in $L^2(\mathrm{SO}(3))$.  Evaluating at $g$ and noting that $\widetilde\Phi^{*}(g^{-1}\rho) = \Phi(\rho^{-1}g)$,
\relax{equation}
  \int_{\mathrm{SO}(3)} W(\rho)\,\Phi(\rho^{-1}g)\,\mathrm{d}\mu(\rho) = \int_{\mathrm{SO}(3)}\widetilde\Phi^{*}(g^{-1}\rho)\,W(\rho)\,\mathrm{d}\mu(\rho) = (\widetilde\Phi\star W)(g) ,
\relax{equation}
so that the synthesis is $\mathcal{C}_{G\to s}[\widetilde\Phi]W$, which is $(\mathcal{C}_{s\to G}[\Phi])^{\dagger}W$ by Theorem~\relax{thm:harmonic}.  In harmonic space, $\widetilde\Phi^{\ell}_{-s,m'} = \Phi^{\ell *}_{m',-s} = (-1)^s\sqrt{8\pi^2/(2\ell+1)}\,\prescript{}{s}{\psi}^{*}_{\ell m'}$ by \eqref{eq:lift-harmonic}, so that \eqref{eq:harmonic-Gs} gives
\relax{equation}
  (\mathcal{C}_{G\to s}[\widetilde\Phi]W)_{\ell m} = (-1)^s\sqrt{\tfrac{2\ell+1}{8\pi^2}}\sum_{m'}W^{\ell}_{mm'}\,(-1)^s\sqrt{\tfrac{8\pi^2}{2\ell+1}}\,\prescript{}{s}{\psi}_{\ell m'} = \sum_{m'}W^{\ell}_{mm'}\,\prescript{}{s}{\psi}_{\ell m'} ,
\relax{equation}
the constants cancelling.

With $\Psi_h(g) = h^{*}(g^{-1}\eta)$ and $k = g^{-1}g'$, $\Psi^{*}_h(g^{-1}g') = h(k^{-1}\eta) = h(g'^{-1}g\eta)$, so that by Definition~\relax{def:group-conv}
\relax{equation}
  (\Psi_h\star\Lambda_{0}f)(g) = \frac{1}{\sqrt{2\pi}}\int_{\mathrm{SO}(3)}h(g'^{-1}g\eta)\,f(g'\eta)\,\mathrm{d}\mu(g') .
\relax{equation}
Applying $\Lambda_{0}^{\dagger}$ at the point $\omega = (\beta,\alpha)$ integrates over $\gamma$ with $g = R(\alpha,\beta,\gamma)$, and since $g\eta = \omega$ does not depend on $\gamma$ the integrand is constant, whence $(\mathcal{C}_{0\to 0}[\Psi_h]f)(\omega) = \frac{1}{2\pi}\cdot 2\pi\int h(g'^{-1}\omega)f(g'\eta)\,\mathrm{d}\mu(g') = (f\star_{\mathrm{L}}h)(\omega)$, exactly.  For the constant, only the entry $(\Psi_h)^{\ell}_{00}$ is read by \eqref{eq:harmonic-ss}.  Writing $g = R(\alpha,\beta,\gamma)$, the point $g^{-1}\eta = R_z(-\gamma)R_y(-\beta)\eta$ has colatitude $\beta$ and longitude $\pi - \gamma$, and $D^{\ell}_{00}(g) = d^{\ell}_{00}(\beta) = P_\ell(\cos\beta) = \sqrt{4\pi/(2\ell+1)}\,Y_{\ell 0}(\beta,\cdot)$, so that
\relax{align}
  (\Psi_h)^{\ell}_{00} &= \int_{\mathrm{SO}(3)}h^{*}(\beta,\pi-\gamma)\,\sqrt{\tfrac{4\pi}{2\ell+1}}\,Y_{\ell 0}(\beta)\,\sin\beta\,\mathrm{d}\alpha\,\mathrm{d}\beta\,\mathrm{d}\gamma \notag\\
  &= 2\pi\sqrt{\tfrac{4\pi}{2\ell+1}}\int_{S^2}h^{*}(\omega')\,Y_{\ell 0}(\omega')\,\mathrm{d}\mu(\omega')
  = 2\pi\sqrt{\tfrac{4\pi}{2\ell+1}}\;h^{*}_{\ell 0} ,
\relax{align}
where the integral over $\alpha$ gives $2\pi$ and the substitution $\varphi' = \pi - \gamma$ runs over a full period.  Hence \eqref{eq:harmonic-ss} with $s = s' = 0$ gives $(f\star_{\mathrm{L}}h)_{\ell m} = f_{\ell m}\,(\Psi_h)^{\ell *}_{00} = 2\pi\sqrt{4\pi/(2\ell+1)}\,f_{\ell m}h_{\ell 0}$, which is \eqref{eq:driscoll-healy-harmonic}, with no conjugate on $h$ since the pairing \eqref{eq:driscoll-healy} is bilinear.  Finally, the marginalisation over $\gamma$ of the bilinear directional convolution $\int f(\omega)(\mathcal{R}_\rho h)(\omega)\,\mathrm{d}\mu(\omega)$, which is a function on $\mathrm{SO}(3)$, is by definition $\sqrt{2\pi}$ times its projection $\Lambda_{0}^{\dagger}$.

Wallis \mbox{\it et al.}\ \relax{wallis2022mapping} write the shear as
\relax{equation}
  \prescript{}{2}{\gamma}(\omega) = \int_{S^2}(\mathcal{R}_{\omega'}\prescript{}{2}{K})(\omega)\,\kappa(\omega')\,\mathrm{d}\mu(\omega'),
\relax{equation}
with an axisymmetric spin-$2$ kernel, $\prescript{}{2}{K}_{\ell m} = \prescript{}{2}{K}_{\ell 0}\delta_{m0}$.  By \eqref{eq:rotation-coeffs} and \eqref{eq:D-sY},
\relax{equation}
  (\mathcal{R}_{\omega'}\prescript{}{2}{K})_{\ell m} = D^{\ell}_{m0}(\varphi',\theta',0)\,\prescript{}{2}{K}_{\ell 0} = \sqrt{\tfrac{4\pi}{2\ell+1}}\,Y^{*}_{\ell m}(\omega')\,\prescript{}{2}{K}_{\ell 0} ,
\relax{equation}
and integrating against $\kappa$ gives $\prescript{}{2}{\gamma}_{\ell m} = \sqrt{4\pi/(2\ell+1)}\,\prescript{}{2}{K}_{\ell 0}\,\kappa_{\ell m}$, a multiplier from spin $0$ to spin $2$; it is $\mathcal{C}_{0\to 2}[\Psi_T]$ with $c_\ell = \sqrt{4\pi/(2\ell+1)}\,\prescript{}{2}{K}_{\ell 0}$ by Theorem~\relax{thm:classification}, and its kernel is \eqref{eq:nogo-kernel} with $(s,s') = (0,2)$: the integral is the adjoint synthesis of the spin-$2$ to scalar axisymmetric analysis of Proposition~\relax{prop:axisymmetric}, not that forward analysis.  The choice $\prescript{}{2}{K}_{\ell 0} = \sqrt{(2\ell+1)/4\pi}\,\mathcal{D}_\ell$ gives $c_\ell = \mathcal{D}_\ell$, which is the spherical Kaiser--Squires relation.

Let $F=\Psi\star\Lambda_{s}f$.  It is continuous, and $\lVert F\rVert_\infty\le\lVert\Psi\rVert_2\lVert f\rVert_2$ by Cauchy--Schwarz and the isometry of the lift, so section evaluation is a bounded map into the coordinate $L^2$ space.  The explicit support hypothesis $\Psi^\ell_{n,-s}=0$ for $\lvert n\rvert\ge N$ makes its fibre decomposition a finite sum.  Evaluating each term at $\sigma(x)=s(x)R_z(\chi_\sigma(x))$ gives \eqref{eq:section-evaluation}, since $\Lambda_{q}^{\dagger}F=\mathcal{C}_{s\to q}[\Psi]f$.

Suppose $E_\sigma$ is equivariant into spin $t$ with the fixed coordinate-frame action.  By Theorem~\relax{thm:classification} it acts on degree $\ell$ by a scalar $\lambda_\ell$, or annihilates that degree if $\ell<\lvert t\rvert$.  Put $a_{\ell q}=(-1)^{s+q}\Psi^{\ell *}_{-q,-s}/\sqrt{2\pi}$.  Testing on every $\prescript{}{s}{Y}_{\ell m}$ gives, almost everywhere,
\relax{equation}
  \sum_{\substack{\lvert q\rvert<N\\\lvert q\rvert\le\ell}}
  a_{\ell q}e^{-\mathrm{i} q\chi_\sigma(x)}\prescript{}{q}{Y}_{\ell m}(x)
  =\lambda_\ell\prescript{}{t}{Y}_{\ell m}(x),
  \relax{eq:section-evaluation-test}
\relax{equation}
with the right-hand side interpreted as zero when $\ell<\lvert t\rvert$.  For a fixed $x$, the vectors $(\prescript{}{q}{Y}_{\ell m}(x))_{m=-\ell}^{\ell}$ for distinct admissible $q$ are nonzero multiples of distinct columns of a unitary Wigner matrix, by \eqref{eq:app-sY-d}.  They are therefore independent.  Since there are countably many tests, a common full-measure set may be used.  Comparing columns in \eqref{eq:section-evaluation-test} forces $a_{\ell q}=0$ for $q\ne t$ and all components to vanish when the target degree is absent.  If some $a_{\ell t}\ne0$, its column gives $e^{-\mathrm{i} t\chi_\sigma(x)}=\lambda_\ell/a_{\ell t}$ almost everywhere.  Thus the phase is constant.  If every coefficient vanishes, $E_\sigma=0$, which is equivariant into every target spin independently of the section.  Conversely, one active output spin and a constant phase give a scalar multiple of $\mathcal{C}_{s\to t}$ and hence equivariance.

For polar rotations, $R_z(a)s(x)=s(R_z(a)x)$ away from the poles, so all spins act by coordinate rotation.  The phase for $\sigma_0$ is constant.  For $\chi_\sigma=\pi-\varphi$, one has $\chi_\sigma(R_z(-a)x)=\chi_\sigma(x)+a$ modulo $2\pi$.  Testing harmonics and comparing the same independent columns shows that commutation is equivalent to $a_{\ell q}(1-e^{-\mathrm{i} qa})=0$ for every $\ell,q$.  This is $e^{\mathrm{i} qa}=1$ for every active spin $q$, including the vacuous condition for the zero map; it makes no assertion about non-polar symmetries.
